import{_ as r,C as o,o as s,c as e,j as i,E as l,a as d,a3 as n}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse(`{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (Android)","link":"/mentor/9-sinf-android/"},"n":1,"bob":"I-bob · Android muhiti va dasturlash asoslari","lessons":[{"g":1,"title":"Android nima va uning rivojlanish tarixi","lead":"Android nima va uning rivojlanish tarixi: mobil OS tarixi, Google, versiyalar va O'zbekiston ekotizimi","link":"/mentor/9-sinf-android/hafta-01/dars-1","slide":"/slaydlar/9-sinf-android/hafta-01/dars-1.html","test":"/slaydlar/9-sinf-android/hafta-01/dars-1-test.html"},{"g":2,"title":"Android tizimi va uning arxitekturasi","lead":"Android tizimi va arxitekturasi: Linux Kernel, HAL, ART/Dalvik, kutubxonalar va Java API Framework","link":"/mentor/9-sinf-android/hafta-01/dars-2","slide":"/slaydlar/9-sinf-android/hafta-01/dars-2.html","test":"/slaydlar/9-sinf-android/hafta-01/dars-2-test.html"},{"g":3,"title":"Androidning imkoniyatlari va qo‘llanilish sohalari","lead":"Androidning imkoniyatlari va qo‘llanilish sohalari: smartfon, planshet, WearOS, Android Auto, Android TV va IoT","link":"/mentor/9-sinf-android/hafta-01/dars-3","slide":"/slaydlar/9-sinf-android/hafta-01/dars-3.html","test":"/slaydlar/9-sinf-android/hafta-01/dars-3-test.html"}],"test":"/slaydlar/9-sinf-android/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-android/hafta-01/index.md","filePath":"mentor/9-sinf-android/hafta-01/index.md"}`),h={name:"mentor/9-sinf-android/hafta-01/index.md"},u={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},v={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function b(k,a,y,f,q,A){const t=o("Icon");return s(),e("div",null,[i("div",u,[i("h2",m,[l(t,{name:"house"}),a[0]||(a[0]=d(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=n('<p>Ushbu haftada o&#39;tilgan darslar bo&#39;yicha mustaqil amaliy uyga vazifalar ro&#39;yxati:</p><hr><h2 id="_1-dars-android-nima-va-uning-rivojlanish-tarixi" tabindex="-1">1-dars. Android nima va uning rivojlanish tarixi <a class="header-anchor" href="#_1-dars-android-nima-va-uning-rivojlanish-tarixi" aria-label="Permalink to &quot;1-dars. Android nima va uning rivojlanish tarixi&quot;">​</a></h2><ol><li>Shaxsiy smartfoningiz (yoki oila a&#39;zolaringizdan birining telefoni) sozlamalariga kirib, uning Android versiyasini, modelini va texnik parametrlarini (RAM, protsessor) aniqlang va daftaringizga yozing.</li><li>«Android versiyasi» ustiga bir necha bor bosib, yashirin Easter Egg o&#39;yinini oching va uning qisqa tasvirini yozing.</li><li>O&#39;zbekistonda yaratilgan va o&#39;zingiz faol foydalanadigan 3 ta mobil ilovani tanlang. Ularning qaysi funksiyalari aholiga eng ko&#39;p qulaylik keltirayotganini tahlil qiling.</li></ol><hr><h2 id="_2-dars-android-tizimi-va-uning-arxitekturasi" tabindex="-1">2-dars. Android tizimi va uning arxitekturasi <a class="header-anchor" href="#_2-dars-android-tizimi-va-uning-arxitekturasi" aria-label="Permalink to &quot;2-dars. Android tizimi va uning arxitekturasi&quot;">​</a></h2><ol><li>Android arxitekturasining 5 ta qatlamini (Linux Kernel, HAL, ART/Libraries, Java API Framework, Applications) chizib, daftaringizda ko&#39;p qavatli bino shaklida tasvirlang.</li><li>Nima sababdan Android 5.0 dan boshlab eski Dalvik (JIT) virtual mashinasidan zamonaviy ART (AOT) tizimiga o&#39;tildi? Asosiy texnik sabablarni yozing.</li><li>«Application Sandbox» nima va u telefoningizdagi bank ilovalari (Click, Payme) xavfsizligini qanday ta&#39;minlashini tushuntiring.</li></ol><hr><h2 id="_3-dars-androidning-imkoniyatlari-va-qo-llanilish-sohalari" tabindex="-1">3-dars. Androidning imkoniyatlari va qo‘llanilish sohalari <a class="header-anchor" href="#_3-dars-androidning-imkoniyatlari-va-qo-llanilish-sohalari" aria-label="Permalink to &quot;3-dars. Androidning imkoniyatlari va qo‘llanilish sohalari&quot;">​</a></h2><ol><li>Smartfoningizda ekranni ikkiga bo&#39;lish (Split-screen) rejimini yoqing va uning afzalliklari bo&#39;yicha qisqa xulosa yozing.</li><li>Aqlli soat (Wear OS) va televizor (Android TV) interfeyslarini taqqoslovchi jadval tuzing: ekran o&#39;lchami, boshqaruv turi va dasturchiga qo&#39;yiladigan talablar.</li><li>Tasavvur qiling, siz maktabingiz uchun Android asosida ishlaydigan aqlli kiosk yaratmoqchisiz. Ushbu kiosk qanday apparat qismlaridan (ekran, kamera, NFC) foydalanishi va unda qanday ilova bo&#39;lishi kerakligini yozma bayon qiling.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-100-ballik-tizim" tabindex="-1">Baholash mezonlari (100 ballik tizim) <a class="header-anchor" href="#baholash-mezonlari-100-ballik-tizim" aria-label="Permalink to &quot;Baholash mezonlari (100 ballik tizim)&quot;">​</a></h3><ol><li><p><strong>Android tarixi va ekotizimi tahlili (30 ball):</strong></p><ul><li>Android Inc., Andy Rubin va Google xaridi tarixini to&#39;g&#39;ri tushunishi (10 ball);</li><li>Versiyalar rivojlanishi va shirinlik nomlaridan raqamlarga o&#39;tish sababini bilishi (10 ball);</li><li>Mahalliy mobil ilovalar va bozor tahlilini asosli ifodalashi (10 ball).</li></ul></li><li><p><strong>Arxitektura va xavfsizlik modeli (40 ball):</strong></p><ul><li>5 ta vertikal qatlamni to&#39;g&#39;ri joylashtirishi va vazifalarini bayon qilishi (15 ball);</li><li>Dalvik (JIT) va ART (AOT) o&#39;rtasidagi farqni unumdorlik va batareya tejamkorligi nuqtai nazaridan asoslay olishi (15 ball);</li><li>Linux yadrosi va Application Sandbox xavfsizlik modelini to&#39;g&#39;ri tushunishi (10 ball).</li></ul></li><li><p><strong>Qo&#39;llanilish sohalari va adaptiv dizayn (30 ball):</strong></p><ul><li>Wear OS, Android Auto va Android TV farqlarini to&#39;g&#39;ri ajratishi (15 ball);</li><li>Kiosk yoki IoT loyihasi g&#39;oyasini texnik jihatdan to&#39;g&#39;ri ifodalashi (15 ball).</li></ul></li></ol><h3 id="kutiladigan-namunaviy-natijalar" tabindex="-1">Kutiladigan namunaviy natijalar <a class="header-anchor" href="#kutiladigan-namunaviy-natijalar" aria-label="Permalink to &quot;Kutiladigan namunaviy natijalar&quot;">​</a></h3><ul><li>O&#39;quvchi Android shunchaki telefon emas, balki Linux yadrosiga qurilgan global platforma ekanini chuqur tushunishi shart;</li><li>Arxitektura tahlilida ilovalarning alohida UID ostida izolyatsiyalanishi va ART ning ilovani oldindan (AOT) mashina kodiga kompilyatsiya qilishi aniq ko&#39;rsatilishi kerak.</li></ul>',16))]),i("div",v,[i("h2",g,[l(t,{name:"list-checks"}),a[3]||(a[3]=d(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=n('<p><strong>Mavzular:</strong></p><ol><li>Android nima va uning rivojlanish tarixi: mobil OS tarixi, Google xaridi, versiyalar va O&#39;zbekiston ekotizimi</li><li>Android tizimi va arxitekturasi: Linux Kernel, HAL, ART/Dalvik, kutubxonalar va Java API Framework</li><li>Androidning imkoniyatlari va qo‘llanilish sohalari: smartfon, planshet, WearOS, Android Auto, Android TV va IoT</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Android tarixi va ekotizim</strong></td><td>Android Inc., Andy Rubin, Google xaridi, versiyalar evolyutsiyasi va mahalliy ilovalar</td><td>30 ball</td></tr><tr><td><strong>Tizim arxitekturasi</strong></td><td>5 ta qatlam, Linux Kernel, HAL, ART vs Dalvik (AOT vs JIT), Sandbox xavfsizligi</td><td>40 ball</td></tr><tr><td><strong>Qo&#39;llanilish sohalari</strong></td><td>Multitasking, on-device AI, Wear OS, Android Auto, Android TV va IoT tushunchalari</td><td>30 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Tarix (30)</th><th>Arxitektura (40)</th><th>Imkoniyatlar (30)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar ko&#39;pincha Androidni faqat telefon interfeysi deb o&#39;ylashadi. Linux yadrosi va apparat ta&#39;minoti (HAL) o&#39;rtasidagi bog&#39;liqlikni hamda har bir ilova alohida UID (foydalanuvchi) sifatida ishga tushishini vizual misollar bilan tushuntirish talab etiladi.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> O&#39;quvchilarga o&#39;z telefonlarida &quot;Developer Options&quot; (Dasturchi sozlamalari) bo&#39;limini faollashtirish va undagi ko&#39;rsatkichlarni (masalan, &quot;Show layout bounds&quot; yoki &quot;Profile HWUI rendering&quot;) tadqiq qilish topshirilishi mumkin.</li></ul>',11))])])}const x=r(h,[["render",b]]);export{z as __pageData,x as default};
